def projection_unpaid(self, operation, error, cell=None):
    row = dict(operation=operation, type=type(error).__name__, message=str(error),
        original_cell=copy.deepcopy(cell), diagnostic_only=True)
    self.projection_error_count += 1
    if self.first_projection_error is None:
        self.first_projection_error = copy.deepcopy(row)
    self.last_projection_error = copy.deepcopy(row)
    return row

def projection_cell(self, cell, tube_record):
    if self.reference_projection is None:
        return dict(schema=PROJECTION_SCHEMA+"-cell", original_cell=copy.deepcopy(cell),
            available=False, reasons=["actual_R575_binding_unpaid"],
            error=copy.deepcopy(self.projection_binding_error),
            original_metric_split_and_acceptance_not_changed=True)
    try:
        return self.reference_projection.inspect(cell, tube_record)
    except (ResourceStop, MemoryError):
        raise
    except Exception as error:
        detail = self.projection_unpaid("same_return_inspect", error, cell)
        return dict(schema=PROJECTION_SCHEMA+"-cell", original_cell=copy.deepcopy(cell),
            available=False, reasons=["actual_R575_observer_return_unpaid"],
            error=detail, original_metric_split_and_acceptance_not_changed=True)

def projection_retirement(self, cell, diagnostic, split):
    if self.current.field.pieces[cell["piece_index"]]["kind"] != "prefix":
        return None
    if self.reference_projection is None:
        return dict(original_cell=copy.deepcopy(cell), original_split=split,
            terminal_projection_ingredient_paid=False,
            reasons=["actual_R575_binding_unpaid"],
            actual_binding_error_in_necessary_scope=True)
    try:
        return self.reference_projection.commit_original_retirement(
            cell, diagnostic, split=split)
    except (ResourceStop, MemoryError):
        raise
    except Exception as error:
        return dict(original_cell=copy.deepcopy(cell), original_split=split,
            terminal_projection_ingredient_paid=False,
            reasons=["actual_R575_retirement_unpaid"],
            error=self.projection_unpaid("original_retirement", error, cell))

def projection_summary(self, coverage, close_errors):
    original = None
    if self.reference_projection is not None:
        try:
            original = self.reference_projection.summary(original_coverage=coverage,
                complete_cell_ledger=self.members.get("complete_cell_ledger"),
                original_error=self.error, original_stop=self.stop, close_errors=close_errors)
        except (ResourceStop, MemoryError):
            raise
        except Exception as error:
            self.projection_unpaid("complete_original_cover_summary", error)
    complete = (isinstance(original, dict)
        and original.get("complete_prefix_physical_angle_projection_bound") is True
        and self.projection_error_count == 0)
    return dict(schema=SCHEMA+"-actual-R575-necessary-v1",
        requested_source=dict(file=PROJECTION_NAME, sha256=PROJECTION_SHA),
        actual_loaded_source=copy.deepcopy(self.sources.get(PROJECTION_NAME)),
        actual_binding_attempted=self.projection_binding_attempted,
        actual_binding_error=copy.deepcopy(self.projection_binding_error),
        original_R575_summary=original,
        observer_error_count=self.projection_error_count,
        first_observer_error=copy.deepcopy(self.first_projection_error),
        last_observer_error=copy.deepcopy(self.last_projection_error),
        complete_prefix_physical_angle_projection_bound=complete,
        all_per_cell_returns_and_retirements_in_original_cell_ledger=True,
        complete_cell_ledger=copy.deepcopy(self.members.get("complete_cell_ledger")),
        original_pending_scope="coverage and members.complete_coverage_and_pending",
        original_ledger_rows_not_all_retransmitted=True,
        ordinary_diagnostic_failure_not_a_metric_or_refinement_rejection=True,
        resource_and_signal_stop_use_original_measurement_path=True,
        exact_reference_projection_not_floating_FFT_or_metric_floor=True)

